package by.bsuir.notification;
import by.bsuir.repair.contract.*; import by.bsuir.repair.runtime.*; import io.grpc.Status; import io.grpc.stub.StreamObserver; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.kafka.annotation.KafkaListener; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.time.*; import java.util.*;
@Service public class NotificationGrpcService extends NotificationServiceGrpc.NotificationServiceImplBase {
 private final JdbcTemplate jdbc; private final Jsons jsons; public NotificationGrpcService(JdbcTemplate jdbc,Jsons jsons){this.jdbc=jdbc;this.jsons=jsons;}
 @KafkaListener(topics={EventTopics.REQUEST,EventTopics.WORK_ORDER,EventTopics.PAYMENT,EventTopics.USER}) @Transactional public void consume(String raw){var envelope=jsons.read(raw);UUID eventId=UUID.fromString(envelope.get("eventId").toString());if(jdbc.queryForObject("select count(*) from processed_events where event_id=?",Integer.class,eventId)>0)return;var payload=jsons.read(envelope.get("payload").toString());String type=envelope.get("eventType").toString();String client=Objects.toString(payload.getOrDefault("clientId",payload.get("userId")),null);if(client!=null&&Set.of("RepairRequestStatusChanged","WorkOrderStatusChanged","WorkOrderCompleted","PaymentCompleted","PaymentFailed","UserRegistered").contains(type)){String message=switch(type){case "PaymentCompleted"->"Платеж успешно зарегистрирован";case "PaymentFailed"->"Не удалось выполнить платеж";case "WorkOrderCompleted"->"Ремонт завершен";case "UserRegistered"->"Регистрация успешно завершена";default->"Статус ремонта изменен: "+Objects.toString(payload.getOrDefault("currentStatus","обновлен"));};jdbc.update("insert into notifications(id,user_id,event_id,type,channel,message,delivery_status,read_at,created_at) values(?,?,?,?,?,?,?,?,?)",UUID.randomUUID(),UUID.fromString(client),eventId,type,"IN_APP",message,"DELIVERED",null,java.time.OffsetDateTime.now(java.time.ZoneOffset.UTC));}jdbc.update("insert into processed_events(event_id,processed_at) values(?,?)",eventId,java.time.OffsetDateTime.now(java.time.ZoneOffset.UTC));}
 @Override public void listNotifications(JsonMessage req,StreamObserver<JsonMessage> obs){try{var in=jsons.read(req);UUID user=UUID.fromString(jsons.string(in,"currentUserId"));boolean unread=jsons.bool(in,"unreadOnly",false);jsons.reply(obs,jdbc.queryForList("select id,user_id AS \"clientId\",type,type AS title,channel,message,delivery_status AS \"deliveryStatus\",(read_at is not null) AS read,read_at AS \"readAt\",created_at AS \"createdAt\" from notifications where user_id=?"+(unread?" and read_at is null":"")+" order by created_at desc",user));}catch(Throwable e){jsons.fail(obs,e);}}
 @Override @Transactional public void markRead(JsonMessage req,StreamObserver<JsonMessage> obs){try{var in=jsons.read(req);UUID id=UUID.fromString(jsons.string(in,"id")),user=UUID.fromString(jsons.string(in,"currentUserId"));if(jdbc.update("update notifications set read_at=? where id=? and user_id=?",java.time.OffsetDateTime.now(java.time.ZoneOffset.UTC),id,user)==0)throw Status.NOT_FOUND.withDescription("Notification not found").asRuntimeException();jsons.reply(obs,jdbc.queryForMap("select id,user_id AS \"clientId\",type,type AS title,channel,message,delivery_status AS \"deliveryStatus\",(read_at is not null) AS read,read_at AS \"readAt\",created_at AS \"createdAt\" from notifications where id=?",id));}catch(Throwable e){jsons.fail(obs,e);}}
}


